// Generated by Suite Builder from a crawl of the site. The suite as a zip to hand on: java pack/Pack.java, from the
// suite's folder.
// EDIT RULES: do not edit this file; regenerating replaces all of it. Account files go in blank; what is left out, and
// why, is listed when it runs.
// Creator: https://github.com/ghost-in-the-kernel
import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.text.Normalizer;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Stream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

/**
 * The suite as a zip to hand on: java pack/Pack.java from the suite's folder (Java 17; no Maven,
 * nothing to download). Beside the suite, &lt;folder&gt;-pack-&lt;date&gt;.zip, with every account file blank
 * (secrets/*.login), the pages as crawled (crawl/pages/, whatever the crawl's age: the receiver needs what was
 * crawled), and none of what a run leaves or a receiver brings back. It says what it carried and left out, and why.
 *
 * <p>{@code java pack/Pack.java --run}: this run's pack, to send to whoever helps with its failures
 *. &lt;folder&gt;-run-&lt;date&gt;.zip: the suite as above, and the run's failures (each one's
 * screenshot, what it saw, why it failed) and reports, without the pages as crawled and without the
 * step-by-step replays; {@code --trace <test name>} adds the replay of each failure whose folder names it.
 */
public final class Pack {
    /** What is left out, by path prefix, and why (the same in every framework Suite Builder writes). */
    static final List<String[]> LEAVES_OUT = List.of(
            new String[] {".git/", "the repository: the receiver keeps their own"},
            new String[] {"target/", "Maven builds it again, and a run's evidence stays with whoever ran it"},
            new String[] {"node_modules/", "npm ci brings it back"},
            new String[] {"cypress/failures/", "a run's evidence stays with whoever ran it"},
            new String[] {"cypress/screenshots/", "a run's evidence stays with whoever ran it"},
            new String[] {"cypress/videos/", "a run's evidence stays with whoever ran it"},
            new String[] {"cypress/results/", "a run's output"},
            new String[] {"cypress/downloads/", "a run's output"},
            new String[] {"cypress/timings/", "a run's output"},
            new String[] {"cypress/timings-previous/", "a run's output"},
            new String[] {"crawl/history/",
                    "earlier crawls, kept for the next rebuild: the receiver gets the crawl the suite is built from"},
            new String[] {"cypress/report.html", "a run's output"},
            new String[] {"cypress/flaky-tests.txt", "a run's output"},
            new String[] {"cypress/rules-report.md", "a run's output"},
            new String[] {"cypress/link-report.md", "a run's output"});
    static final String BLANK_ACCOUNT = "Username:\nPassword:\n";
    /**
     * The longest path in the zip that still unzips on Windows (260 characters, less room for where it is unzipped).
     */
    static final int LONGEST_PATH = 160;
    /** What a run's pack adds: the run's evidence and reports, by path prefix. */
    static final List<String> RUN_TAKES = List.of("target/failures/", "target/report.html", "target/flaky-tests.txt",
            "target/link-report.md", "target/rules-report.md", "cypress/failures/", "cypress/screenshots/",
            "cypress/report.html", "cypress/flaky-tests.txt", "cypress/link-report.md", "cypress/rules-report.md");
    /** The file a failure's step-by-step replay is saved as (null: this framework keeps none). */
    static final String REPLAY = "/trace.zip";
    static final String WHY_NO_REPLAY =
            "a step-by-step replay, about 13 MB each: --trace <test name> adds the one you need";
    /**
     * The suite's pages mode (crawl/manifest.json, pages.ship): all, public-only or local; unscrubbed: pages saved
     * before the cleaning of today.
     */
    static String pagesMode = "unknown";
    /**
     * What a pack that carries pages read signed in says (the words of Suite Builder's own warning); <folder> is this
     * suite's folder.
     */
    static final String SIGNED_IN_WARNING =
            "WARNING: this suite's crawl pages include pages seen signed in. They can hold a person's data (names, "
            + "addresses, orders). Pushing this repository to a public host can expose them. To keep them off git: "
            + "`suite build <folder> --crawl-pages public-only`.";

    public static void main(String[] args) throws IOException {
        Path suite = Path.of("").toAbsolutePath();
        boolean run = List.of(args).contains("--run");
        pagesMode = pagesModeOf(suite);
        int t = List.of(args).indexOf("--trace");
        String trace = t >= 0 && t + 1 < args.length ? args[t + 1].toLowerCase() : null;
        if (run && !Files.isDirectory(suite.resolve("target/failures"))
                && !Files.exists(suite.resolve("target/report.html"))) {
            System.out.println("No run here to pack: run the tests first (mvn test), then pack it.");
            System.exit(1);
        }
        String folderName = suite.getFileName() == null ? "suite" : suite.getFileName().toString();
        Path zip = suite.resolveSibling(folderName + (run ? "-run-" : "-pack-") + LocalDate.now() + ".zip");
        Map<String, Integer> left = new TreeMap<>();
        Map<String, String> why = new TreeMap<>();
        int blanked = 0;
        int pages = 0;
        int signedIn = 0;
        int packed = 0;
        String longest = "";
        List<Path> taken = new ArrayList<>();
        try (Stream<Path> walk = Files.walk(suite)) {
            for (Path file : walk.filter(Files::isRegularFile).sorted().toList()) {
                String rel = suite.relativize(file).toString().replace('\\', '/');
                String reason = run ? runLeftOut(rel, trace) : null;
                if (reason == null && !(run && runTakes(rel))) reason = leftOut(rel);
                if (reason == null && !run) reason = pagesLeftOut(rel);
                if (run && reason == null && rel.startsWith("crawl/pages/")) reason =
                        "the pages as crawled: the crawl file holds what they showed, and they can hold personal data";
                if (reason != null) {
                    String group = group(rel);
                    left.merge(group, 1, Integer::sum);
                    why.put(group, reason);
                    continue;
                }
                taken.add(file);
                if (rel.startsWith("crawl/pages/")) pages++;
                if (rel.startsWith("crawl/pages/_as=") || rel.startsWith("crawl/pages/api/_as=")) signedIn++;
            }
        }
        // Every name checked before anything is written: one that is not portable stops the pack, named with the fix. A
        // run's
        // evidence, named by the test runner, is not the suite's own and goes in as it is.
        // Too long a path or name, and one file twice but for case (Windows and macOS keep one), stop it too.
        List<String> odd = new ArrayList<>();
        Map<String, String> byCase = new TreeMap<>();
        for (Path file : taken) {
            String rel = suite.relativize(file).toString().replace('\\', '/');
            if (run && runTakes(rel)) continue;
            String problem = notPortable(rel);
            if (problem != null) {
                odd.add("  " + rel + ": " + problem + ". Fix: " + portableFix(rel, folderName) + ".");
                continue;
            }
            String tooLong = tooLong(rel);
            if (tooLong != null) odd.add("  " + rel + ": " + tooLong + ". Fix: shorten it.");
            String same = byCase.putIfAbsent(rel.toLowerCase(), rel);
            if (same != null) odd.add("  " + rel + ": the same file as " + same
                    + " on Windows and macOS. Fix: rename one of the two.");
        }
        if (!odd.isEmpty()) {
            System.out.println("Not packed: " + odd.size() + " name" + (odd.size() == 1 ? "" : "s")
                    + " would stop this zip on Windows, which takes only A-Z a-z 0-9 . _ - = in a suite's names:");
            odd.forEach(System.out::println);
            System.exit(1);
        }
        try (ZipOutputStream out = new ZipOutputStream(Files.newOutputStream(zip))) {
            for (Path file : taken) {
                String rel = suite.relativize(file).toString().replace('\\', '/');
                String entry = folderName + "/" + rel;
                if (entry.length() > longest.length()) longest = entry;
                out.putNextEntry(new ZipEntry(entry));
                // Every account file blank, whatever this copy holds: the receiver fills in their own.
                if (rel.startsWith("secrets/") && rel.endsWith(".login")) {
                    out.write(BLANK_ACCOUNT.getBytes(StandardCharsets.UTF_8));
                    blanked++;
                } else {
                    Files.copy(file, (OutputStream) out);
                }
                out.closeEntry();
                packed++;
            }
        }
        System.out.println("Packed " + packed + " files into " + zip + ", "
                + String.format("%.1f", Files.size(zip) / 1048576.0) + " MB (" + blanked + " account file"
                + (blanked == 1 ? "" : "s") + " blank).");
        if (pages > 0) System.out.println("With the pages as crawled: crawl/pages/ (" + pages + " file"
                + (pages == 1 ? "" : "s") + "), whatever the crawl's age.");
        if (signedIn > 0) System.out.println("With " + signedIn + " page" + (signedIn == 1 ? "" : "s")
                + " read signed in. " + SIGNED_IN_WARNING.replace("<folder>", folderName));
        if (!left.isEmpty()) System.out.println("Left out:");
        left.forEach(
                (group, count) -> System.out.println("  " + group + " (" + count + " file" + (count == 1 ? "" : "s")
                + "): " + why.get(group)));
        if (longest.length() > LONGEST_PATH) System.out.println("Too long for Windows' zip once unzipped ("
                + longest.length() + " characters; at most " + LONGEST_PATH + "): " + longest
                + ". Shorten that name before handing it on.");
        if (run) System.out.println(
                "The screenshots and page.html files show the site as the run saw it: signed in, they can show an "
                + "account's data. Look before you send it.");
        else System.out.println(
                "Hand it on as it is; never a copy with a filled account file. The receiver fills in secrets/ "
                + "(secrets/README.md).");
    }

    /**
     * Why a name in the suite would stop its zip on Windows, or null: a character outside A-Z a-z 0-9 . _ - =, a name
     * Windows
     * keeps for a device, a trailing dot or space. Suite Builder names every file so; a suite built before it did can
     * hold one.
     */
    static String notPortable(String rel) {
        for (String piece : rel.split("/")) {
            for (int i = 0; i < piece.length(); i = piece.offsetByCodePoints(i, 1)) {
                int c = piece.codePointAt(i);
                boolean plain = (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.'
                        || c == '_' || c == '=' || c == '-';
                if (!plain) return "\"" + new String(Character.toChars(c)) + "\" (U+" + String.format("%04X", c) + ")";
            }
            if (piece.matches("(?i)(con|prn|aux|nul|com[1-9]|lpt[1-9])(\\..*)?")) return "\"" + piece
                    + "\" is a name Windows keeps for a device";
            if (piece.endsWith(".") || piece.endsWith(" ")) return "\"" + piece
                    + "\" ends in a dot or a space, which Windows drops";
        }
        return null;
    }

    /**
     * Why a name is too long for Windows once unzipped, or null: a path over LONGEST_PATH, a file or folder name over
     * 100.
     */
    static String tooLong(String rel) {
        if (rel.length() > LONGEST_PATH) return rel.length() + " characters, more than " + LONGEST_PATH
                + " (Windows' 260, less room for the folder it is unzipped in)";
        for (String piece : rel.split("/")) if (piece.length() > 100) return "\"" + piece + "\" is " + piece.length()
                + " characters, more than 100";
        return null;
    }

    /**
     * The one line that fixes a name that is not portable: the pages as crawled are renamed by a rebuild; any other is
     * renamed by hand.
     */
    static String portableFix(String rel, String folder) {
        if (rel.startsWith("crawl/pages/")) return "rebuild the suite (suite build " + folder
                + "): it renames the pages as crawled";
        String plain = Normalizer.normalize(rel, Normalizer.Form.NFKD).replaceAll("\\p{M}", "")
                .replaceAll("[^A-Za-z0-9._=/-]", "_");
        return "rename it to " + plain;
    }

    /** Why a file stays out of the zip; null when it goes in. */
    static String leftOut(String rel) {
        for (String[] out : LEAVES_OUT) if (rel.equals(out[0])
                || (out[0].endsWith("/") && rel.startsWith(out[0]))) return out[1];
        if (rel.startsWith("saved-pages/")
                && (rel.endsWith(".html")
                || rel.endsWith(".htm"))) return "saved pages can hold personal data: each receiver saves their own";
        return null;
    }

    /** The mode the suite's manifest records; all when it records none. */
    static String pagesModeOf(Path suite) {
        try {
            String manifest = Files.readString(suite.resolve("crawl/manifest.json"));
            // Only the `pages` object of the manifest says it (it holds no object of its own, so it ends at the first
            // brace).
            java.util.regex.Matcher block = java.util.regex.Pattern.compile("\"pages\":\\s*\\{([^}]*)\\}")
                    .matcher(manifest);
            if (!block.find()) return "unknown";
            if (java.util.regex.Pattern.compile("\"unscrubbed\":\\s*true").matcher(block.group(1))
                    .find()) return "unscrubbed";
            java.util.regex.Matcher ship = java.util.regex.Pattern.compile("\"ship\":\\s*\"([a-z-]+)\"")
                    .matcher(block.group(1));
            // No record, or one Suite Builder does not know, is read on the safe side: unknown.
            return ship.find() && List.of("all", "public-only", "local")
                    .contains(ship.group(1)) ? ship.group(1) : "unknown";
        } catch (IOException e) {
            return "unknown";
        }
    }

    /** Why a crawl page stays out of the plain pack in the suite's pages mode; null when it goes in. */
    static String pagesLeftOut(String rel) {
        if (!rel.startsWith("crawl/pages/")) return null;
        if (pagesMode.equals(
                "local")) return "pages mode local (crawl/manifest.json): the crawl's pages stay on the computer that "
                + "crawled; rebuild with --crawl-pages all to carry them";
        if (pagesMode.equals(
                "unscrubbed")) return "saved before Suite Builder cleaned pages as it does now: a recrawl brings clean "
                + "ones";
        boolean signedIn = rel.startsWith("crawl/pages/_as=") || rel.startsWith("crawl/pages/api/_as=");
        if (pagesMode.equals("public-only")
                && signedIn) return "pages mode public-only (crawl/manifest.json): pages read signed in stay on the "
                + "computer that crawled";
        if (pagesMode.equals("unknown")
                && signedIn) return "crawl/manifest.json records no pages mode (or one this version does not know): "
                + "pages read signed in stay out; rebuild the suite to record it";
        return null;
    }

    /** In a run's pack: a run's evidence and reports go in, the plain pack's rules aside. */
    static boolean runTakes(String rel) {
        for (String take : RUN_TAKES) if (rel.equals(take) || (take.endsWith("/") && rel.startsWith(take))) return true;
        return false;
    }

    /** Why a run's pack leaves a file out that the run's evidence holds: a trace not asked for by name. */
    static String runLeftOut(String rel, String trace) {
        if (REPLAY == null || !rel.endsWith(REPLAY)) return null;
        return trace != null && rel.toLowerCase().contains(trace) ? null : WHY_NO_REPLAY;
    }

    /** What a left-out file is said as: its folder, or itself. */
    static String group(String rel) {
        if (REPLAY != null && rel.endsWith(REPLAY)) return "the step-by-step replays";
        for (String[] out : LEAVES_OUT) if (rel.startsWith(out[0])) return out[0];
        if (rel.startsWith("saved-pages/")) return "saved-pages/ (the pages; its README goes in)";
        if (rel.startsWith("crawl/pages/")) return "crawl/pages/";
        return rel;
    }
}
